// Kernel and program descriptors for kcl (generated by gen_kernels.py from .ze_info or patch tokens). Offsets in the cross-thread data,
// -1 = absent. arg: off/size -- a value or a stateless address; ptr -- pointer argument; bti -- index in the binding table
// (stateful); off_addr / off_boff -- buffer_address / buffer_offset for stateful.
#pragma once
#include <stddef.h>
#include <stdint.h>

struct kcl_arg_desc { int16_t off, size, ptr, bti, off_addr, off_boff; };

struct kcl_kernel_desc {
    const char *name; const uint8_t *isa; uint32_t isa_len;
    uint32_t simd, cross, per_thread, lid, nargs;
    struct kcl_arg_desc arg[24];
    int16_t off_ls[3], off_els[3], off_gid[3], off_gs[3], off_ng[3], off_wdim, off_const, off_priv;
    uint32_t private_size, slm, barrier, nbti;
    const char *unsupported;   // "" = supported
};

struct kcl_program_desc {
    const char *file, *options;     // options = NULL: binary from the assembler (program_bin)
    const struct kcl_kernel_desc *kernels; uint32_t nkernels;
    const uint8_t *constants; uint32_t nconstants;
};

extern const struct kcl_program_desc kcl_programs[];        // Gen9.5 (kernels.c)
extern const int kcl_nprograms;
extern const struct kcl_program_desc kcl_programs_gen8[];   // Gen8 (kernels_gen8.c, docs/gen8.md)
extern const int kcl_nprograms_gen8;
